/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Tile sizes tuned for a modern multi-core x64 CPU.
# 64x64x64 gives a good balance between cache locality and code size.
TILE_I = 64
TILE_J = 64
TILE_K = 64

@proc
def kernel_gemm_base(
    ni: size,
    nj: size,
    nk: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    C: DATA_TYPE[ni, nj] @ DRAM,
    A: DATA_TYPE[ni, nk] @ DRAM,
    B: DATA_TYPE[nk, nj] @ DRAM,
):
    # Compute C <- beta * C + alpha * A * B with 3D tiling.
    #
    # Outer (I,J) loops iterate over tiles of C.
    # For each C-tile:
    #   1. Scale that tile by beta (single pass, good C locality).
    #   2. Accumulate alpha * A * B across all K-tiles.
    #
    # This preserves the original GEMM semantics but greatly improves
    # cache reuse and memory access patterns.

    # Iterate over tiles in the i (row) dimension.
    for I in seq(0, (ni + TILE_I - 1) / TILE_I):
        # Iterate over tiles in the j (column) dimension.
        for J in seq(0, (nj + TILE_J - 1) / TILE_J):

            # ------------------------------------------------------
            # 1) Scale the current C tile by beta.
            # Loop order (i, j) gives unit-stride accesses in j
            # for C, matching row-major layout.
            # ------------------------------------------------------
            for i in seq(0, TILE_I):
                if I * TILE_I + i < ni:
                    for j in seq(0, TILE_J):
                        if J * TILE_J + j < nj:
                            C[I * TILE_I + i, J * TILE_J + j] = (
                                beta * C[I * TILE_I + i, J * TILE_J + j]
                            )

            # ------------------------------------------------------
            # 2) Accumulate alpha * A * B into the same C tile.
            #
            # Loop order:
            #   for K over k-tiles:
            #     for i in I-tile:
            #       for k in K-tile:
            #         a_val = alpha * A[i,k]     # reused across j
            #         for j in J-tile:          # innermost, unit stride
            #             C[i,j] += a_val * B[k,j]
            #
            # This yields:
            #   - Good temporal reuse of C within the (I,J) tile.
            #   - Reuse of A[i,k] across the entire inner j-loop.
            #   - Contiguous accesses in j for both B[k,j] and C[i,j].
            # ------------------------------------------------------
            for K in seq(0, (nk + TILE_K - 1) / TILE_K):
                for i in seq(0, TILE_I):
                    if I * TILE_I + i < ni:
                        for k in seq(0, TILE_K):
                            if K * TILE_K + k < nk:
                                # Hoist alpha * A[i,k] once per (i,k) so we
                                # do not recompute it for every j.
                                a_val: DATA_TYPE
                                a_val = alpha * A[I * TILE_I + i, K * TILE_K + k]

                                for j in seq(0, TILE_J):
                                    if J * TILE_J + j < nj:
                                        C[I * TILE_I + i, J * TILE_J + j] += (
                                            a_val
                                            * B[K * TILE_K + k, J * TILE_J + j]
                                        )

# Apply scheduling primitives to the tiled kernel.
# We parallelize the outermost I loop: each thread works on a disjoint
# band of rows of C (and the corresponding rows of A). B is read-only.
kernel_gemm = kernel_gemm_base
kernel_gemm = parallelize_loop(kernel_gemm, "I")
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int ni = NI;
  int nj = NJ;
  int nk = NK;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,NI,NJ,ni,nj);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,NI,NK,ni,nk);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,NK,NJ,nk,nj);

  /* Initialize array(s). */
  init_array (ni, nj, nk, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D views to 1D pointers. */
  kernel_gemm (/*ctxt=*/NULL, ni, nj, nk,
	       (DATA_TYPE*)&alpha, (DATA_TYPE*)&beta,
	       (DATA_TYPE*)POLYBENCH_ARRAY(C),
	       (DATA_TYPE*)POLYBENCH_ARRAY(A),
	       (DATA_TYPE*)POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(ni, nj,  POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
