/* Array initialization.
 *
 * NOTE: We store B in a transposed layout compared to the original PolyBench
 * GEMM (NJ x NK instead of NK x NJ). This matches the optimized Exo kernel,
 * where B is indexed as B[j, k] (row-major in j, then k). We initialize B
 * such that B[j, k] == original_B[k, j], so the mathematical result is
 * unchanged.
 */
static
void init_array(int ni, int nj, int nk,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NJ,NK,nj,nk))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;

  /* C initialization: unchanged. */
  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++)
      C[i][j] = (DATA_TYPE) ((i*j+1) % ni) / ni;

  /* A initialization: unchanged. */
  for (i = 0; i < ni; i++)
    for (j = 0; j < nk; j++)
      A[i][j] = (DATA_TYPE) (i*(j+1) % nk) / nk;

  /* B initialization:
   * Original layout: B_orig[k][j] with shape [NK][NJ], row-major.
   * New layout:     B[j][k]     with shape [NJ][NK], row-major.
   *
   * We write:
   *   B[j][i] = (DATA_TYPE) (i*(j+2) % nj) / nj;
   * so that for all k,j:
   *   B[j][k] == original_B[k][j].
   */
  for (i = 0; i < nk; i++)
    for (j = 0; j < nj; j++)
      B[j][i] = (DATA_TYPE) (i*(j+2) % nj) / nj;
}


