from __future__ import annotations

from exo import *
from exo.libs.memories import DRAM
from exo.API_scheduling import *

# Tile sizes chosen for a modern x64 CPU. These are compile-time constants.
# They control cache blocking along i (rows), j (columns), and k (reduction).
TI = 64  # tile size for i (rows of C and A)
TJ = 64  # tile size for j (columns of C and B)
TK = 64  # tile size for k (reduction dimension)

@proc
def kernel_gemm(
    ni: size,
    nj: size,
    nk: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    C: DATA_TYPE[ni, nj] @ DRAM,
    A: DATA_TYPE[ni, nk] @ DRAM,
    B: DATA_TYPE[nj, nk] @ DRAM,
):
    # Tiled GEMM:
    #   C[ni, nj] = beta * C + alpha * A[ni, nk] * B_T[nk, nj]
    #
    # where B is stored transposed as [nj, nk] in row-major order. This makes
    # the j-dimension of both C[i, j] and B[j, k] contiguous in memory and
    # improves cache and TLB behavior.
    #
    # We first scale C by beta, tile by (TI, TJ), and then accumulate alpha*A*B
    # into the same tiles, blocked over k by TK.

    # Iterate over tiles of rows (I) and columns (J) of C.
    for I in seq(0, (ni + TI - 1) / TI):
        for J in seq(0, (nj + TJ - 1) / TJ):
            # 1. Scale the current C tile by beta.
            for i in seq(0, TI):
                # Global row index.
                if TI * I + i < ni:
                    for j in seq(0, TJ):
                        # Global column index.
                        if TJ * J + j < nj:
                            C[TI * I + i, TJ * J + j] = beta * C[TI * I + i, TJ * J + j]

            # 2. Accumulate alpha * A * B into the same C tile, blocked over k.
            #
            #    for each K-tile, we touch a TI x TK panel of A and a
            #    TJ x TK panel of B, reusing them across many C[i, j].
            for K in seq(0, (nk + TK - 1) / TK):
                for i in seq(0, TI):
                    if TI * I + i < ni:
                        for k in seq(0, TK):
                            if TK * K + k < nk:
                                # Hoist alpha * A[global_i, global_k] so it is reused
                                # across all j in the tile. This reduces one multiply
                                # per (i, k, j) and keeps the scalar in a register.
                                a_val: DATA_TYPE
                                a_val = alpha * A[TI * I + i, TK * K + k]
                                for j in seq(0, TJ):
                                    if TJ * J + j < nj:
                                        # B is indexed as B[global_j, global_k] because it
                                        # is stored transposed (nj x nk).
                                        C[TI * I + i, TJ * J + j] += \
                                            a_val * B[TJ * J + j, TK * K + k]

# Parallelize over outer tiles of rows in C. Different I-tiles write to
# disjoint row ranges of C, so these iterations are independent.
kernel_gemm_sched = kernel_gemm
kernel_gemm_sched = parallelize_loop(kernel_gemm_sched,
                                     kernel_gemm_sched.find_loop("I"))
kernel_gemm = kernel_gemm_sched
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int ni = NI;
  int nj = NJ;
  int nk = NK;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,NI,NJ,ni,nj);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,NI,NK,ni,nk);
  /* B is now stored as [NJ][NK] (row-major), matching the Exo kernel. */
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,NJ,NK,nj,nk);

  /* Initialize array(s). */
  init_array (ni, nj, nk, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D views to 1D pointers. */
  kernel_gemm (/*ctxt=*/NULL, ni, nj, nk,
	       (DATA_TYPE*)&alpha, (DATA_TYPE*)&beta,
	       (DATA_TYPE*)POLYBENCH_ARRAY(C),
	       (DATA_TYPE*)POLYBENCH_ARRAY(A),
	       (DATA_TYPE*)POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(ni, nj,  POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
